def count_ways(commands):
    n = len(commands)
    dp = [[0] * n for _ in range(n)]

    # Initialize the first row
    for i in range(n):
        dp[i][i] = 1

    # Fill the dp table
    for i in range(1, n):
        for j in range(i):
            if commands[j] == 'U':
                dp[i][j] = dp[i-1][j]
            elif commands[j] == 'R':
                dp[i][j] = dp[i-1][j+1]
            elif commands[j] == 'D':
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = dp[i-1][j]

    # The number of ways to return to the starting square is the sum of the last row
    return sum(dp[-1])

# Read input
n = int(input())
commands = input()

# Print the result
print(count_ways(commands))
