import sys

def solve():
    n, k = map(int, sys.stdin.readline().split())
    grid = [list(sys.stdin.readline()) for _ in range(n)]
    insect_pos = None

    for i in range(n):
        if grid[i][0] == 'G':
            insect_pos = (i, 0)
            break

    for i in range(n):
        if grid[i][-1] == 'G':
            insect_pos = (i, n-1)
            break

    if insect_pos is None:
        return "NO"

    for i in range(1, n):
        if grid[insect_pos[0]][i] == 'G':
            continue

        for j in range(1, k+1):
            if grid[insect_pos[0]][j] == '.':
                grid[insect_pos[0]][j] = 'G'
                break

    for i in range(n-1, -1, -1):
        if grid[i][insect_pos[1]] == 'G':
            continue

        for j in range(k+1, 0, -1):
            if grid[i][j] == '.':
                grid[i][j] = 'G'
                break

    return "YES"

if __name__ == "__main__":
    solve()
